vector<int> findClosestElements(vector<int>& arr, int k, int x) {
    vector<int> v = arr;
    sort(v.begin(), v.end(), [x](int a, int b) {
        return abs(a - x) != abs(b - x) ? abs(a - x) < abs(b - x) : a < b;   // ties: smaller first
    });
    v.resize(k);
    sort(v.begin(), v.end());
